INSERT INTO public.timeline_museum (id, categoria, tipo, titulo, subtitulo, siglo_texto, extracto, relato_historico, significado_cultural, dato_curioso, coste_desbloqueo)
VALUES
  ('lc-hammurabi', 'historia', 'codice', 'El Código de Hammurabi', 'Edad Antigua · Babilonia', '1750 a.C.', '''Para que el fuerte no dañe al débil y se haga justicia al huérfano y a la viuda.''', 'El surgimiento de la ley escrita limitó la arbitrariedad de los gobernantes y fundó las bases del derecho civil: una regla conocida por todos.', 'Gana 1 partida en la categoría Historia', 'Estaba tallado en una estela de diorita negra de más de 2 metros. Incluye 282 leyes y fue uno de los primeros intentos de establecer leyes públicas para que ningún rey las cambiara a su antojo.', 70),
  ('lc-bastilla', 'historia', 'codice', 'Toma de la Bastilla', 'Edad Contemporánea · Francia', '1789 d.C.', '''¿Es una revuelta?'' —preguntó el Rey. ''No, Majestad, es una revolución.''', 'Dio origen a la ''Declaración de los Derechos del Hombre y del Ciudadano'', instaurando los principios universales de Libertad, Igualdad y Fraternidad.', 'Acierta 5 cartas seguidas en Historia', 'El día de la toma de la fortaleza, el rey Luis XVI escribió en su diario personal una sola palabra: ''Rien'' (Nada), creyendo que era una protesta menor. Al día siguiente descubrió que había comenzado una revolución.', 60),
  ('lc-carta-magna', 'historia', 'codice', 'La Carta Magna en Runnymede', 'Edad Media · Inglaterra', '1215 d.C.', '''A nadie venderemos, a nadie negaremos ni retrasaremos el derecho o la justicia.''', 'Consagró el principio jurídico del ''Habeas Corpus'': ningún hombre libre puede ser apresado o castigado sin un juicio legítimo por sus pares.', 'Gana 2 partidas en Historia Universal', 'El rey Juan fue forzado a firmarla en una pradera pantanosa a orillas del Támesis porque los barones no se fiaban de entrar a su castillo.', 75),
  ('lc-caida-roma', 'historia', 'codice', 'La Caída del Imperio Romano de Occidente', 'Antigüedad Tardía · Rávena, Italia', '476 d.C.', '''Roma duró doce siglos desde que Rómulo trazó su primer surco.''', 'Los grandes imperios no suelen colapsar por un solo golpe militar externo, sino por el desgaste institucional y la desintegración interna paulatina.', 'Coloca 6 acontecimientos históricos correctamente', 'El último emperador se llamaba casualmente ''Rómulo'' (como el primer rey de Roma) y ''Augústulo'' (pequeño Augusto, como el primer emperador).', 75),
  ('lc-templo-salomon', 'biblia', 'codice', 'El Templo de Salomón', 'Monarquía Unida · Jerusalén', '957 a.C.', '''El principio de la sabiduría es el temor del Señor.'' (Proverbios 1:7)', 'Simbolizó la transición del pueblo nómada a una nación establecida con un centro espiritual y de sabiduría que atrajo a mandatarios de todo el mundo antiguo.', 'Gana 1 partida en Estudio Bíblico', 'Fue construido con cedros del Líbano. Las piedras fueron talladas en las canteras lejanas para que no se escuchara ningún sonido de martillo de hierro en el lugar sagrado durante su edificación.', 70),
  ('lc-rollo-mar-muerto', 'biblia', 'codice', 'Los Rollos de Qumrán (Mar Muerto)', 'Período del Segundo Templo · Judea', '150 a.C.', '''Sécase la hierba, marchítase la flor; mas la palabra del Dios nuestro permanece para siempre.'' (Isaías 40:8)', 'Comprobó que los textos bíblicos se habían copiado y transmitido con una fidelidad asombrosa durante más de mil años de historia.', 'Acierta 4 cartas bíblicas seguidas', 'Fueron descubiertos en 1947 por un joven pastor beduino que arrojó una piedra a una cueva buscando una cabra perdida y escuchó el sonido de vasijas de arcilla quebrándose.', 75),
  ('lc-septuaginta', 'biblia', 'codice', 'La Septuaginta (Biblia de los Setenta)', 'Período Helenístico · Alejandría, Egipto', '250 a.C.', '''Lámpara es a mis pies tu palabra, y lumbrera a mi camino.'' (Salmos 119:105)', 'La traducción de las Escrituras al idioma universal de la época preparó el camino para la difusión del Evangelio en el mundo grecorromano.', 'Gana 1 ronda bíblica', 'Fue la primera vez en la historia que las Sagradas Escrituras hebreas se tradujeron a otra lengua (el griego koiné), permitiendo que la fe fuera conocida por todo el Mediterráneo.', 60),
  ('lc-sermon-monte', 'biblia', 'codice', 'El Manifiesto del Sermón del Monte', 'Siglo I d.C. · Galilea', '28 d.C.', '''Vosotros sois la luz del mundo; una ciudad asentada sobre un monte no se puede esconder.'' (Mateo 5:14)', 'Estableció una ética espiritual basada en el amor desinteresado y la rectitud interior por encima del mero cumplimiento ritual exterior.', 'Supera 1 ronda con 3 vidas intactas', 'Pronunciado en una colina junto al Mar de Galilea, contiene enseñanzas revolucionarias como amar a los enemigos y poner la otra mejilla.', 75),
  ('lc-copernico', 'ciencia', 'codice', 'La Revolución Heliocéntrica de Copérnico', 'Renacimiento Científico · Polonia', '1543 d.C.', '''En el centro de todo reposa el Sol.'' — Nicolás Copérnico', 'El ''Giro Copernicano'' transformó la posición del ser humano en el cosmos: la Tierra no era el centro estático del universo, sino un planeta más en órbita.', 'Gana 1 partida en la categoría Ciencia', 'Copérnico recibió el primer ejemplar impreso de su libro ''De revolutionibus orbium coelestium'' en su lecho de muerte, el mismo día en que falleció.', 70),
  ('lc-telescopio-galileo', 'ciencia', 'codice', 'El Telescopio de Galileo Galilei', 'Revolución Científica · Padua, Italia', '1609 d.C.', '''Y sin embargo, se mueve.'' (''E pur si muove'')', 'La ciencia moderna exige observación experimental por encima de los dogmas y argumentos de autoridad.', 'Acierta 4 cartas científicas seguidas', 'Galileo pulió personalmente las lentes de su telescopio para multiplicar por treinta el aumento del ojo humano, descubriendo montañas en la Luna y las cuatro lunas de Júpiter.', 60),
  ('lc-penicilina', 'ciencia', 'codice', 'Descubrimiento de la Penicilina', 'Siglo XX · Londres, Reino Unido', '1928 d.C.', '''Uno a veces encuentra lo que no está buscando.'' — Alexander Fleming', 'La serenidad y agudeza mental para observar lo inesperado: la penicilina inauguró la era de los antibióticos salvando cientos de millones de vidas.', 'Gana 2 partidas en Ciencia e Invenciones', 'Fleming regresó de sus vacaciones de verano y notó que un hongo (Penicillium notatum) había contaminado por accidente una placa de bacterias destruyéndolas.', 75),
  ('lc-anticitera', 'ciencia', 'codice', 'El Mecanismo de Anticitera', 'Grecia Helenística · Isla de Anticitera', '150 a.C.', '''Una obra maestra de precisión astronómica que desafió al tiempo bajo el mar.''', 'Reescribió la historia de la tecnología: los antiguos griegos dominaban engranajes diferenciales 1.500 años antes de lo registrado en Europa.', 'Alcanza racha de 8 aciertos en Ciencia', 'Rescatado en 1901 de un naufragio romano, es la computadora analógica más antigua del mundo: calculaba con 37 engranajes de bronce las órbitas solares, lunares y eclipses.', 85),
  ('lc-beethoven-novena', 'musica', 'codice', 'La Novena Sinfonía de Beethoven', 'Romanticismo · Viena, Austria', '1824 d.C.', '''¡Abrazaos, millones de seres! ¡Este beso para el mundo entero!'' — Oda a la Alegría', 'El triunfo indomable del espíritu humano: la sordera no impidió a Beethoven componer el Himno de la Alegría proclamando la fraternidad universal.', 'Gana 1 partida en la categoría Música', 'Beethoven estaba completamente sordo durante el estreno. La contralto Caroline Unger tuvo que tomarlo suavemente del brazo y girarlo hacia el público para que viera la ovación de pie.', 70),
  ('lc-cuatro-estaciones', 'musica', 'codice', 'Las Cuatro Estaciones de Vivaldi', 'Barroco Musical · Venecia / Ámsterdam', '1725 d.C.', '''La música es un lenguaje que no necesita palabras para despertar la primavera en el corazón.''', 'Demostró la capacidad sinestésica de la música para pintar paisajes sonoros y evocar sensaciones físicas con maestría instrumental.', 'Acierta 4 cartas musicales seguidas', 'Es la primera gran obra de ''música programática'': cada concierto incluía un soneto explicativo de Vivaldi imitando el ladrido de perros, el trinar de pájaros y tormentas de verano.', 60),
  ('lc-flauta-magica', 'musica', 'codice', 'La Flauta Mágica de Mozart', 'Clasicismo Vienés · Viena, Austria', '1791 d.C.', '''La música no está en las notas, sino en el silencio que hay entre ellas.'' — Mozart', 'Unión perfecta del cuento de hadas popular con profundas alegorías sobre la búsqueda de la sabiduría y el triunfo de la luz sobre la oscuridad.', 'Gana 2 partidas en Música y Arte', 'Fue estrenada en un teatro popular suburbano apenas dos meses antes del prematuro fallecimiento de Mozart a los 35 años.', 75),
  ('lc-woodstock-paz', 'musica', 'codice', 'El Festival de Woodstock de 1969', 'Contracultura de los 60 · Bethel, Nueva York', '1969 d.C.', '''Tres días de paz, amor y música.''', 'Consagró a la música como catalizador sociológico y voz unificadora del pacifismo y la juventud de una era.', 'Acierta 5 canciones o hitos musicales', 'Se esperaban 50.000 personas y llegaron más de 400.000 desbordando vallas bajo lluvias torrenciales sin incidentes de violencia en ''tres días de paz y música''.', 75),
  ('lc-metropolis', 'cine', 'codice', 'Metrópolis y el Futuro Distópico', 'Expresionismo Alemán · Berlín', '1927 d.C.', '''El mediador entre la cabeza y las manos debe ser el corazón.''', 'Pionera de la ciencia ficción cinematográfica: advirtió sobre la deshumanización del progreso industrial sin empatía social.', 'Gana 1 partida en Cine y Pop', 'Fue la primera película inscrita en el Registro de la ''Memoria del Mundo'' de la UNESCO. El diseño del robot humanoide María inspiró directamente a C-3PO de Star Wars.', 70),
  ('lc-viaje-luna', 'cine', 'codice', 'El Viaje a la Luna de Méliès', 'Cine Primitivo · París, Francia', '1902 d.C.', '''Un cohete incrustado en el ojo sonriente de la Luna que cambió el arte para siempre.''', 'El cine dejó de ser un simple registro documental de la realidad para convertirse en la fábrica de los sueños y la fantasía visual.', 'Acierta 4 cartas de cine seguidas', 'Méliès era un mago e ilusionista teatral. Inventó por casualidad el truco de sustitución cinematográfico (''jump cut'') cuando su cámara se atascó en una calle de París.', 60),
  ('lc-mago-oz', 'cine', 'codice', 'El Mago de Oz y la Magia del Technicolor', 'Época Dorada de Hollywood · EE.UU.', '1939 d.C.', '''No hay lugar como el hogar.'' (''There''s no place like home'')', 'Revolución estética del color: demostró el poder emocional de la paleta cromática en la pantalla grande.', 'Gana 2 partidas en Cine y Entretenimiento', 'El paso del sepia al color cuando Dorothy abre la puerta de la cabaña al Mundo de Oz se filmó pintando el interior de sepia y usando a una doble vestida de marrón.', 75),
  ('lc-star-wars-1977', 'cine', 'codice', 'Star Wars: Una Nueva Esperanza', 'Nuevo Hollywood · Los Ángeles, EE.UU.', '1977 d.C.', '''Que la Fuerza te acompañe.''', 'Revolucionó el arquetipo del mito del héroe combinando naves espaciales, sables de luz y efectos prácticos de Industrial Light & Magic.', 'Acierta 6 cartas de cine y cultura pop', 'Los directivos de 20th Century Fox pensaban que la película sería un fracaso; Lucas cedió su sueldo de director a cambio de los derechos de mercadotecnia y secuelas.', 75),
  ('lc-termopilas-codice', 'conflictos', 'codice', 'Los 300 Espartanos en las Termópilas', 'Guerras Médicas · Grecia', '480 a.C.', '''Caminante, ve y di a los espartanos que aquí yacemos por obedecer sus leyes.''', 'El sacrificio heroico en inferioridad numérica puede infundir un coraje moral capaz de salvar a toda una civilización.', 'Gana 1 partida en la categoría Conflictos y Batallas', 'Leónidas seleccionó exclusivamente a guerreros que ya tuvieran hijos varones para que su estirpe familiar continuara viva en Esparta.', 70),
  ('lc-canas-codice', 'conflictos', 'codice', 'El Doble Envolvimiento de Cannas', 'Segunda Guerra Púnica · Apulia, Italia', '216 a.C.', '''Hallaremos un camino, o lo abriremos.'' — Aníbal Barca', 'La obra maestra de la táctica de cerco militar: la inteligencia geográfica y la sincronización pesan más que la superioridad numérica bruta.', 'Acierta 4 batallas en orden cronológico', 'Aníbal aniquiló a 50.000 legionarios romanos rodeándolos con una fuerza inferior en número que cedió en el centro para atraparlos.', 75),
  ('lc-waterloo-codice', 'conflictos', 'codice', 'El Ocaso de Napoleón en Waterloo', 'Guerras Napoleónicas · Bélgica', '1815 d.C.', '''La batalla más reñida que jamás haya presenciado en mi vida.'' — Wellington', 'El fin definitivo de la era napoleónica y el reordenamiento del equilibrio de poder diplomático europeo en el Congreso de Viena.', 'Gana 2 partidas en Conflictos y Batallas', 'Una lluvia torrencial la noche anterior dejó el suelo fangoso obligando a Napoleón a esperar a que secara, permitiendo la llegada del ejército prusiano.', 75),
  ('lc-stalingrado-codice', 'conflictos', 'codice', 'La Resistencia de Stalingrado', 'Segunda Guerra Mundial · URSS', '1942 d.C.', '''Más allá del Volga para nosotros no hay tierra.''', 'El punto de inflexión decisivo de la Segunda Guerra Mundial: quebró el avance del ejército nazi e inició la contraofensiva hacia Berlín.', 'Alcanza racha de 6 aciertos en Batallas', 'La batalla urbana se libró fábrica por fábrica e incluso piso por piso; la estación de tren central de la ciudad cambió de bando quince veces en un solo día.', 80),
  ('lc-marco-polo-codice', 'exploraciones', 'codice', 'El Libro de las Maravillas de Marco Polo', 'Ruta de la Seda · Venecia / Génova', '1298 d.C.', '''No he contado ni la mitad de lo que realmente vi.'' — Marco Polo', 'Abrió los ojos de Europa hacia la inmensidad, sofisticación y riquezas del Lejano Oriente inspirando dos siglos después los viajes de Colón.', 'Gana 1 partida en Exploraciones y Navegación', 'En su lecho de muerte sus amigos le rogaron que admitiera que sus historias eran inventadas; Marco Polo respondió: ''¡No he contado ni la mitad de lo que vi!''.', 70),
  ('lc-elcano-vuelta-codice', 'exploraciones', 'codice', 'La Nao Victoria y la Vuelta al Mundo', 'Era de los Descubrimientos · Sanlúcar de Barrameda', '1522 d.C.', '''Primus circumdedisti me'' (Fuiste el primero en rodearme).', 'La prueba empírica irrefutable de que la Tierra es redonda y que todos los océanos del mundo están interconectados.', 'Acierta 4 cartas de exploraciones seguidas', 'De los 247 marineros que partieron en cinco naves desde Sevilla en 1519, sólo 18 exhaustos supervivientes regresaron a bordo de la única nave intacta.', 75),
  ('lc-livingstone-codice', 'exploraciones', 'codice', 'David Livingstone en las Cataratas Victoria', 'Exploración Africana · Río Zambeze', '1855 d.C.', '''Iré a cualquier parte, con tal de que sea hacia adelante.'' — David Livingstone', 'Abrió las rutas científicas hacia el interior de África combatiendo el comercio clandestino de esclavos en el continente.', 'Gana 1 ronda en Exploraciones', 'Los indígenas llamaban a la colosal catarata ''El humo que truena''. Livingstone quedó tan conmovido que escribió que los ángeles debían contemplarla en su vuelo.', 60),
  ('lc-everest-codice', 'exploraciones', 'codice', 'La Conquista del Techo del Mundo (Everest)', 'Alpinismo del Siglo XX · Himalaya', '1953 d.C.', '''No conquistamos a la montaña, sino a nosotros mismos.'' — Edmund Hillary', 'La fraternidad y cooperación entre culturas para desafiar los límites extremos de la resistencia física humana.', 'Coloca 6 acontecimientos de rutas correctamente', 'En la cumbre a 8.848 metros de altitud pasaron 15 minutos; el sherpa Tenzing enterró galletas y dulces en la nieve como ofrenda budista a la montaña sagrada.', 80),
  ('lc-quijote-codice', 'arte', 'codice', 'Don Quijote de la Mancha', 'Siglo de Oro Español · Madrid', '1605 d.C.', '''La libertad, Sancho, es uno de los más preciosos dones que a los hombres dieron los cielos.''', 'La primera novela polifónica moderna: un himno inmortal al idealismo, la libertad individual y la bondad frente a la crudeza de la realidad.', 'Gana 1 partida en Arte y Literatura', 'Cervantes concibió la novela en una celda de la prisión de Sevilla donde estuvo encarcelado por disputas administrativas de recaudación de impuestos.', 70),
  ('lc-hamlet-codice', 'arte', 'codice', 'La Tragedia de Hamlet de Shakespeare', 'Teatro Isabelino · Londres, Inglaterra', '1601 d.C.', '''Hay más cosas en el cielo y en la tierra, Horacio, que las que sospecha tu filosofía.''', 'La obra maestra de la introspección dramática: expone la fragilidad de la razón humana atrapada entre la moral y la acción.', 'Acierta 4 cartas de arte seguidas', 'El famoso monólogo ''Ser o no ser'' explora las dudas existenciales y el miedo a lo desconocido tras la muerte con una hondura psicológica sin precedentes.', 60),
  ('lc-meninas-codice', 'arte', 'codice', 'Las Meninas de Diego Velázquez', 'Barroco Español · Madrid', '1656 d.C.', '''Un lienzo que pinta el propio acto de mirar.''', 'La ''Teología de la Pintura'': demostró que el arte no es una mera artesanía manual, sino un acto intelectual supremo de filosofía visual.', 'Gana 2 partidas en Arte y Filosofía', 'Velázquez se autorretrató pintando un lienzo gigantesco mientras en un espejo al fondo se reflejan los reyes de España, convirtiendo al espectador en el verdadero centro de la escena.', 75),
  ('lc-caverna-platon', 'arte', 'codice', 'El Mito de la Caverna de Platón', 'Filosofía Clásica · Atenas, Grecia', '375 a.C.', '''La ignorancia es la noche de la mente, pero una noche sin luna ni estrellas.''', 'El deber de la educación y el pensamiento crítico: liberarse de las apariencias y prejuicios para buscar la verdad auténtica.', 'Acierta 6 obras filosóficas y literarias', 'Alegoría de hombres encadenados en una cueva oscura que toman las sombras proyectadas en la pared como la única realidad hasta que uno escapa hacia la luz del sol.', 80),
  ('lc-maraton-1896-codice', 'deportes', 'codice', 'Spyridon Louis y la Maratón de Atenas 1896', 'Renacimiento Olímpico · Atenas, Grecia', '1896 d.C.', '''¡Un griego ha ganado la carrera de Maratón!''', 'El renacer del ideal olímpico: unir a las naciones del mundo a través de la competencia atlética pacífica y la superación personal.', 'Gana 1 partida en Deportes y Hazañas', 'El pastor de agua griego se detuvo en una posada del camino para tomar una copa de vino que le ofreció su tío antes de coronarse en el Estadio Panathinaikó.', 70),
  ('lc-owens-berlin-codice', 'deportes', 'codice', 'La Lección Olímpica de Jesse Owens', 'Juegos Olímpicos de Berlín 1936 · Alemania', '1936 d.C.', '''Las batallas que cuentan no son las de las medallas de oro, sino las luchas internas contra la injusticia.''', 'El deporte como el escenario supremo de igualdad: el mérito, la velocidad y la dignidad humana no entienden de razas ni fronteras.', 'Acierta 4 cartas deportivas seguidas', 'Owens ganó cuatro medallas de oro demoliendo la propaganda racista de la supremacía aria en su propio estadio olímpico.', 75),
  ('lc-gol-del-siglo-codice', 'deportes', 'codice', 'El Gol del Siglo de Maradona en México 86', 'Copa del Mundo México 86 · Estadio Azteca', '1986 d.C.', '''¡Barrilete cósmico, ¿de qué planeta viniste?!'' — Víctor Hugo Morales', 'La apoteosis del talento individual en el fútbol: una jugada que trascendió el deporte para convertirse en patrimonio cultural del mundo.', 'Gana 2 partidas en Deportes', 'Recorrió 60 metros en 10 segundos eludiendo a seis jugadores ingleses con once toques mágicos de pierna izquierda.', 75),
  ('lc-dream-team-codice', 'deportes', 'codice', 'El Dream Team de Barcelona 92', 'Juegos Olímpicos Barcelona 92 · España', '1992 d.C.', '''Fue como una banda de rock and roll en gira mundial con una pelota en la mano.''', 'El equipo más dominante en la historia colectiva del deporte: popularizó el baloncesto en todos los rincones del planeta.', 'Coloca 6 acontecimientos deportivos correctamente', 'Ganaron la medalla de oro con una diferencia promedio de 44 puntos por partido sin que su entrenador pidiera un solo tiempo muerto en todo el torneo.', 80),
  ('lc-imprenta', 'historia', 'reliquia', 'La Imprenta de Tipos Móviles', 'Renacimiento · Maguncia, Alemania', '1440 d.C.', '''La imprenta es un ejército de veintiséis soldados de plomo con el que se puede conquistar el mundo.''', 'La democratización del conocimiento: las ideas dejaron de ser monopolio de una élite reducida y dieron origen al Renacimiento, la ciencia moderna y la educación masiva.', 'Carta de Bienvenida / Vence en Duelo Histórico', 'Antes de Gutenberg, un monje tardaba hasta un año entero en copiar una sola Biblia a mano. Gutenberg inventó una aleación especial de plomo, estaño y antimonio que no se deformaba con la tinta caliente.', 120),
  ('lc-rosetta', 'historia', 'reliquia', 'La Piedra de Rosetta', 'Antigüedad · Egipto Ptolemaico', '196 a.C.', '''¡Lo tengo!'' — Exclamó Champollion antes de desmayarse por el impacto de descifrar los jeroglíficos.', 'La traducción y la lingüística comparada abrieron una ventana para que la humanidad comprendiera 3.000 años de civilización egipcia que parecían perdidos para siempre.', 'Vence a Menti en Duelo o alcanza Racha de 3 días', 'La misma ordenanza real estaba tallada en tres escrituras distintas: jeroglífico egipcio, demótico y griego antiguo. Esto permitió a Champollion descifrar el misterio de los jeroglíficos tras más de 1.400 años de silencio.', 150),
  ('lc-piramides-keops', 'historia', 'reliquia', 'La Gran Pirámide de Giza', 'Imperio Antiguo · Egipto', '2560 a.C.', '''El hombre teme al tiempo, pero el tiempo teme a las pirámides.''', 'Proeza insuperable de la ingeniería geométrica y la organización estatal de la antigüedad egipcia.', 'Supera 10 rondas en Modo Supervivencia', 'Fue la construcción humana más alta del planeta durante 3.800 años ininterrumpidos y la única de las Siete Maravillas del Mundo Antiguo que aún sigue en pie.', 200),
  ('lc-declaracion-derechos-humanos', 'historia', 'reliquia', 'Declaración Universal de Derechos Humanos', 'Posguerra · París, Francia (ONU)', '1948 d.C.', '''Todos los seres humanos nacen libres e iguales en dignidad y derechos.''', 'Consagró que todo ser humano nace libre e igual en dignidad y derechos sin distinción de raza, credo, género o condición.', 'Completa el Desafío Diario con 100% de aciertos', 'Fue redactada tras el horror del Holocausto y traducida a más de 500 idiomas, siendo el documento con más traducciones de la historia.', 220),
  ('lc-arca-pacto', 'biblia', 'reliquia', 'El Arca del Pacto', 'Éxodo en el Desierto · Monte Sinaí', '1440 a.C.', '''Y de allí me declararé a ti, y hablaré contigo de sobre el propiciatorio.'' (Éxodo 25:22)', 'Custodiaba tres testimonios fundamentales: las Tablas de la Ley (moral divina), la vara florecida de Aarón (autoridad espiritual) y una vasija de oro con maná (provisión milagrosa).', 'Gana 3 Duelos contra Menti en Estudio Bíblico', 'Construida de madera de acacia y recubierta de oro puro por dentro y por fuera. Encima de ella reposaba el Propiciatorio con dos querubines con alas extendidas donde se manifestaba la gloria divina (''Shejiná'').', 220),
  ('lc-exodo', 'biblia', 'reliquia', 'El Paso del Mar Rojo y las Tablas de la Ley', 'Éxodo · Mar Rojo y Monte Sinaí', '1445 a.C.', '''Jehová peleará por vosotros, y vosotros estaréis tranquilos.'' (Éxodo 14:14)', 'El nacimiento de Israel como nación libre bajo el pacto ético de los Diez Mandamientos, cimiento moral de la civilización occidental.', 'Vence a Menti en Duelo en la categoría Biblia', 'El mar se abrió mediante un fuerte viento oriental que sopló toda la noche formando muros de agua a ambos lados para el paso de cientos de miles de hebreos.', 160),
  ('lc-sudario', 'biblia', 'reliquia', 'El Sudario de Turín y el Sepulcro Vacío', 'Siglo I d.C. · Jerusalén', '33 d.C.', '''No está aquí, pues ha resucitado, como dijo.'' (Mateo 28:6)', 'La Resurrección de Cristo como acontecimiento que transformó a un puñado de pescadores temerosos en apóstoles que llevaron el mensaje cristiano por todo el Imperio Romano.', 'Acierta 10 cartas bíblicas consecutivas', 'Es el objeto arqueológico más examinado científicamente de la historia: la imagen grabada en el lino no contiene pigmentos, tintes ni pinceladas visibles.', 250),
  ('lc-cruz-golgota', 'biblia', 'reliquia', 'La Cruz del Gólgota y la Consumación', 'Siglo I d.C. · Jerusalén', '33 d.C.', '''Consumado es.'' (Juan 19:30)', 'El sacrificio vicario de amor supremo: el perdón incondicional de los pecados y la reconciliación entre Dios y la humanidad.', 'Supera 12 eventos en modo Supervivencia Bíblica', 'A las tres de la tarde la tierra tembló y el velo del Templo de Jerusalén se rasgó en dos de arriba a abajo, simbolizando el acceso directo a la presencia de Dios.', 240),
  ('lc-adn', 'ciencia', 'reliquia', 'La Estructura de Doble Hélice del ADN', 'Siglo XX · Laboratorio Cavendish, Cambridge', '1953 d.C.', '''Hemos descubierto el secreto de la vida.'' — Francis Crick', 'El descubrimiento de la molécula de la herencia genética permitió descifrar el código fundamental de la vida y fundó la biotecnología moderna.', 'Vence a Menti en Duelo en la categoría Ciencia', 'La célebre ''Fotografía 51'' tomada mediante difracción de rayos X por la brillante química Rosalind Franklin fue la evidencia experimental clave para desentrañar la doble hélice.', 160),
  ('lc-mecanismo-anticitera-relic', 'ciencia', 'reliquia', 'El Enigma Cósmico de Anticitera', 'Grecia Antigua · Mar Egeo', '150 a.C.', '''El primer computador del mundo que desafió al tiempo bajo las olas.''', 'La cumbre de la cibernética analógica antigua: prueba que la mente humana alcanzó niveles de sofisticación mecánica milenios antes de la era industrial.', 'Supera el Desafío Diario con 0 fallos', 'Contenía una manivela exterior que permitía adelantar o retroceder el tiempo para observar la posición exacta de los planetas y los eclipses en cualquier fecha.', 220),
  ('lc-apolo-11-relic', 'ciencia', 'reliquia', 'El Módulo Lunar Eagle en el Mar de la Tranquilidad', 'Carrera Espacial · Luna', '1969 d.C.', '''Un pequeño paso para el hombre, un gran salto para la humanidad.''', 'Por primera vez en la historia de la vida en la Tierra, una especie abandonó su planeta cuna para pisar y caminar sobre otro cuerpo celeste.', 'Alcanza una racha de 7 días jugando a Mentrix', 'La computadora de navegación del Apolo 11 tenía solo 4 kilobytes de memoria RAM, miles de veces menos que un teléfono móvil moderno.', 250),
  ('lc-hubble-relic', 'ciencia', 'reliquia', 'El Telescopio Espacial Hubble y el Campo Profundo', 'Astronomía Espacial · Órbita Terrestre Baja', '1990 d.C.', '''Una ventana a través del tiempo hasta el nacimiento de las primeras estrellas.''', 'Nos permitió calcular con precisión la edad del universo (13.800 millones de años) y constatar que el cosmos está en expansión acelerada.', 'Vence a Menti con más de 1.000 puntos', 'Apuntó durante diez días consecutivos a un punto aparentemente negro y vacío del cielo del tamaño de la cabeza de un alfiler, revelando miles de galaxias jamás vistas.', 180),
  ('lc-stradivarius-relic', 'musica', 'reliquia', 'El Violín Stradivarius ''Messiah''', 'Lutería Barroca · Cremona, Italia', '1716 d.C.', '''La perfección de un instrumento que parece tener alma humana al ser rozado por el arco.''', 'La cúspide de la acústica y la artesanía instrumental: ningún instrumento moderno ha logrado igualar la calidez de su sonoridad.', 'Vence a Menti en Duelo Musical con 0 fallos', 'La madera de abeto rojo creció durante la Pequeña Edad de Hielo europea, lo que produjo anillos de crecimiento inusualmente densos que confieren un timbre inigualable.', 220),
  ('lc-mesias-handel-relic', 'musica', 'reliquia', 'El Oratorio ''El Mesías'' y el Coro Aleluya', 'Barroco Inglés · Londres / Dublín', '1741 d.C.', '''¡Aleluya! Porque el Señor nuestro Dios Todopoderoso reina.''', 'La tradición donde el rey Jorge II se puso de pie conmovido en el estreno dio origen a la costumbre mundial de ponerse en pie al escuchar el Aleluya.', 'Gana 2 Duelos en Música y Arte', 'Händel compuso las 260 páginas de partitura en solo 24 días de trance febril; al terminar el coro Aleluya exclamó llorando: ''¡Creí ver el cielo abierto y al mismo Dios!''.', 170)
INSERT INTO public.timeline_museum (id, categoria, tipo, titulo, subtitulo, siglo_texto, extracto, relato_historico, significado_cultural, dato_curioso, coste_desbloqueo)
VALUES
  ('lc-sgt-pepper-relic', 'musica', 'reliquia', 'Sgt. Pepper''s Lonely Hearts Club Band', 'Verano del Amor · Abbey Road Studios, Londres', '1967 d.C.', '''Un momento decisivo en la historia de la cultura occidental del siglo XX.''', 'Elevó la música popular y el rock and roll a la categoría de alta obra de arte conceptual.', 'Supera 8 rondas seguidas en Música', 'Transformó el estudio de grabación en un instrumento musical con orquestaciones de vanguardia, collages sonoros y la portada más famosa del rock.', 160),
  ('lc-thriller-relic', 'musica', 'reliquia', 'Thriller de Michael Jackson', 'Era MTV · Los Ángeles, EE.UU.', '1982 d.C.', '''Porque esto es Thriller, noche de Thriller.''', 'Derribó las barreras raciales en la televisión musical y transformó el videoclip en un cortometraje cinematográfico.', 'Supera 10 eventos en Supervivencia Musical', 'Es el álbum más vendido de todos los tiempos con más de 70 millones de copias certificadas en todo el planeta.', 220),
  ('lc-padrino-relic', 'cine', 'reliquia', 'El Padrino de Francis Ford Coppola', 'Nuevo Cine Americano · Nueva York', '1972 d.C.', '''Le haré una oferta que no podrá rechazar.''', 'Tragedia shakespeariana sobre la corrupción del poder, la familia y el reverso oscuro del sueño americano.', 'Vence a Menti en Duelo en Cine y Cultura Pop', 'Marlon Brando se puso algodón en los carrillos durante la audición para darle a Don Vito Corleone una mandíbula pesada de bulldog.', 160),
  ('lc-toy-story-relic', 'cine', 'reliquia', 'Toy Story y la Revolución de Pixar', 'Animación Digital · Emeryville, California', '1995 d.C.', '''¡Al infinito y más allá!'' — Buzz Lightyear', 'Demostró que la tecnología de vanguardia sólo cobra vida cuando está al servicio de una historia emotiva con personajes entrañables.', 'Gana 3 partidas en Cine y Entretenimiento', 'El primer largometraje de la historia generado enteramente por computadora; cada fotograma tardó hasta 15 horas en renderizarse.', 170),
  ('lc-matrix-relic', 'cine', 'reliquia', 'The Matrix y el ''Bullet Time''', 'Ciencia Ficción Ciberpunk · Sídney / Hollywood', '1999 d.C.', '''Tomas la pastilla azul, la historia acaba... Tomas la pastilla roja, te quedas en el País de las Maravillas.''', 'Unió la filosofía de la caverna de Platón y el simulacro de Baudrillard con artes marciales y efectos visuales revolucionarios.', 'Completa el Desafío Diario en menos de 45 segundos', 'Para filmar a Neo esquivando balas en la azotea colocaron 120 cámaras de fotos fijas en círculo que disparaban en milésimas de segundo coordinadas por ordenador.', 220),
  ('lc-senor-anillos-relic', 'cine', 'reliquia', 'El Señor de los Anillos y el Retorno del Rey', 'Fantasía Épica · Nueva Zelanda', '2003 d.C.', '''Incluso la persona más pequeña puede cambiar el curso del futuro.'' — Galadriel', 'Elevó la fantasía épica a la cima del arte cinematográfico mundial demostrando que hasta la persona más pequeña puede cambiar el curso del futuro.', 'Alcanza racha de 10 aciertos en Cine', 'Ganó los 11 Premios Óscar a los que estuvo nominada, igualando el récord histórico de Ben-Hur y Titanic.', 240),
  ('lc-gaugamela-relic', 'conflictos', 'reliquia', 'La Cuña de Alejandro en Gaugamela', 'Imperio Macedonio · Llanuras de Asiria', '331 a.C.', '''No hay nada imposible para aquel que lo intenta.'' — Alejandro Magno', 'La obra maestra del liderazgo al frente de las tropas: cargó en persona en la punta de la cuña de caballería quebrando el corazón del Imperio Persa.', 'Vence a Menti en Duelo de Batallas con 0 fallos', 'Alejandro durmió tan plácidamente la noche anterior que sus generales tuvieron que despertarlo sacudiéndolo por los hombros al amanecer.', 220),
  ('lc-hastings-tapiz-relic', 'conflictos', 'reliquia', 'El Tapiz de Bayeux y la Batalla de Hastings', 'Conquista Normanda · Inglaterra / Francia', '1066 d.C.', '''Un lienzo que narra cómo cambió la corona de Inglaterra en una sola tarde.''', 'Unió a Inglaterra con el continente europeo transformando para siempre la lengua inglesa y la estructura feudal.', 'Gana 2 partidas en Conflictos y Batallas', 'Un bordado de lino de casi 70 metros de largo que documenta en cincuenta escenas la batalla e incluso el paso del cometa Halley en el cielo.', 170),
  ('lc-lepanto-relic', 'conflictos', 'reliquia', 'La Mayor Batalla Naval de Galeras en Lepanto', 'Edad Moderna · Golfo de Corinto, Grecia', '1571 d.C.', '''La más alta ocasión que vieron los siglos pasados, los presentes, ni esperan ver los venideros.'' — Cervantes', 'Frenó la expansión naval del Imperio Otomano en el Mediterráneo occidental consolidando el comercio naval europeo.', 'Acierta 6 batallas consecutivas en el juego', 'Chocaron más de 400 galeras y galeazas a remo; Cervantes combatió herido de gravedad con fiebre en el esquife del navío Marquesa.', 180),
  ('lc-dia-d-relic', 'conflictos', 'reliquia', 'Operación Overlord: Las Playas del Día D', 'Segunda Guerra Mundial · Normandía, Francia', '1944 d.C.', '''Los ojos del mundo están puestos sobre ustedes.'' — General Eisenhower', 'La apertura del frente occidental que condujo a la liberación de Europa occidental y a la rendición incondicional del nazismo.', 'Supera el Desafío Diario con categoría Batallas', 'La mayor operación anfibia y logística de la historia: 7.000 buques y 156.000 soldados asaltaron las playas Omaha, Utah, Gold, Juno y Sword.', 240),
  ('lc-shackleton-relic', 'exploraciones', 'reliquia', 'La Odisea del Endurance de Sir Ernest Shackleton', 'Edad Heroica Antártica · Mar de Weddell', '1915 d.C.', '''Para liderazgo científico, dame a Scott; para rapidez y eficacia, dame a Amundsen; pero cuando estás en un pozo sin salida, ponte de rodillas y reza por Shackleton.''', 'La mayor lección de liderazgo, resistencia y resiliencia humana bajo condiciones extremas de supervivencia.', 'Supera 10 rondas en Supervivencia de Exploraciones', 'Su barco quedó atrapado y triturado por el hielo; navegó 1.300 km en un bote abierto de 7 metros por los mares más tempestuosos del mundo sin perder un solo hombre.', 240),
  ('lc-amundsen-polo-relic', 'exploraciones', 'reliquia', 'La Bandera Noruega en el Polo Sur de Amundsen', 'Carrera al Polo Sur · Meseta Antártica', '1911 d.C.', '''La victoria espera a quien lo tiene todo en orden; a eso lo llaman suerte.'' — Roald Amundsen', 'La planificación meticulosa y la humildad para aprender de las culturas nativas garantizan el triunfo sobre la improvisación soberbia.', 'Vence a Menti en Duelo de Exploraciones', 'Amundsen aprendió de los inuit árticos a usar trineos tirados por perros esquimales y ropa holgada de piel de foca que permitía transpirar sin congelarse.', 180),
  ('lc-beagle-darwin-relic', 'exploraciones', 'reliquia', 'El Cuaderno de Campo del HMS Beagle', 'Expedición Alrededor del Mundo · Islas Galápagos', '1835 d.C.', '''Hay grandeza en esta concepción de la vida... mientras este planeta ha ido girando según la ley fija de la gravedad.'' — Darwin', 'La expedición científica que dio origen a la Teoría de la Evolución por Selección Natural transformando para siempre la biología.', 'Gana 2 partidas en Exploraciones y Navegación', 'Darwin observó cómo las formas de los caparazones de las tortugas y los picos de los pinzones variaban según la isla y su alimentación disponible.', 170),
  ('lc-trieste-marianas-relic', 'exploraciones', 'reliquia', 'El Batiscafo Trieste en el Abismo Challenger', 'Exploración Abisal · Fosa de las Marianas', '1960 d.C.', '''Tocamos fondo... y ante nuestros ojos vimos nadar tranquilamente a un pez.''', 'Demostró que la vida marina existe incluso en las profundidades abisales más oscuras y extremas de la corteza del planeta.', 'Acierta 8 eventos de exploraciones seguidos', 'Descendieron a 10.916 metros bajo el mar soportando una presión de 1.100 atmósferas que comprimió la esfera de acero varios milímetros.', 230),
  ('lc-mona-lisa-relic', 'arte', 'reliquia', 'La Gioconda de Leonardo da Vinci', 'Alto Renacimiento · Florencia, Italia', '1503 d.C.', '''La simplicidad es la máxima sofisticación.'' — Leonardo da Vinci', 'El icono pictórico más célebre de la historia: la síntesis perfecta entre arte, óptica científica y misterio psicológico humano.', 'Vence a Menti en Duelo de Arte con 0 fallos', 'Aplicó más de 30 capas de pintura microscópica ultrafina con la yema de sus dedos mediante la técnica del ''sfumato'' para lograr su misteriosa sonrisa.', 250),
  ('lc-sixtina-creacion-relic', 'arte', 'reliquia', 'La Creación de Adán en la Capilla Sixtina', 'Renacimiento Italiano · Roma, Vaticano', '1512 d.C.', '''El verdadero artista no es sino el instrumento de una fuerza superior.'' — Miguel Ángel', 'Una de las cumbres pictóricas universales: Miguel Ángel plasmó el aliento de vida y la dignidad del alma humana creada a imagen de Dios.', 'Completa el Desafío Diario con categoría Arte', 'Los dedos de Dios y de Adán están separados por escasos milímetros sin llegar a tocarse, representando la chispa divina del libre albedrío.', 240),
  ('lc-divina-comedia-relic', 'arte', 'reliquia', 'La Divina Comedia de Dante Alighieri', 'Baja Edad Media · Florencia / Rávena', '1320 d.C.', '''El amor que mueve el sol y las demás estrellas.'' (L''amor che move il sole e l''altre stelle)', 'La alegoría del viaje del alma desde las tinieblas del error moral hasta la luz del conocimiento supremo y la redención.', 'Gana 2 Duelos en Arte y Filosofía', 'Estructurada con una rigurosa simetría matemática: 100 cantos en total, divididos en 33 cantos para el Infierno, 33 para el Purgatorio y 33 para el Paraíso más uno introductorio.', 180),
  ('lc-guernica-relic-arte', 'arte', 'reliquia', 'El Guernica de Pablo Picasso', 'Siglo XX · Pabellón Español de París', '1937 d.C.', '''No, la pintura no está hecha para decorar las casas; es un arma de guerra contra la barbarie.'' — Picasso', 'El arte convertido en un grito imperecedero contra la violencia ciega de la guerra y la defensa de la paz mundial.', 'Alcanza racha de 8 aciertos en Arte', 'Picasso utilizó únicamente blanco, negro y una gama de grises para asemejarlo a las fotografías de los periódicos que denunciaban la masacre de civiles inocentes.', 190),
  ('lc-pele-tres-mundiales-relic', 'deportes', 'reliquia', 'Pelé y la Triple Corona Mundial', 'Copas del Mundo · Suecia, Chile y México', '1970 d.C.', '''Nací para el fútbol como Beethoven nació para la música.'' — Pelé', 'La consagración del fútbol como el ''Jogo Bonito'': arte, alegría, destreza acrobática y comunión colectiva.', 'Vence a Menti en Duelo Deportivo con 0 fallos', 'Es el único futbolista en la historia de la humanidad en ganar tres Copas Mundiales de la FIFA (1958, 1962 y 1970).', 240),
  ('lc-ali-rumble-relic', 'deportes', 'reliquia', 'Muhammad Ali y ''The Rumble in the Jungle''', 'Boxeo Histórico · Kinshasa, Zaire', '1974 d.C.', '''Vuela como una mariposa, pica como una abeja.'' — Muhammad Ali', 'La victoria del ingenio táctico, la resiliencia psicológica y la dignidad personal por encima de la fuerza bruta.', 'Supera 10 eventos en Supervivencia Deportiva', 'Inventó la táctica del ''rope-a-dope'' apoyando su espalda en las cuerdas flojas para absorber los golpes de George Foreman hasta noquearlo en el octavo asalto.', 230),
  ('lc-messi-qatar-relic', 'deportes', 'reliquia', 'Lionel Messi y la Coronación de Qatar 2022', 'Copa del Mundo FIFA · Lusail, Qatar', '2022 d.C.', '''¿Qué mirás, bobo? Andá pa'' allá.'' / ''Ya está.'' — Lionel Messi', 'La perseverancia incansable frente a las derrotas previas: nunca rendirse hasta alcanzar el sueño máximo con humildad y liderazgo.', 'Completa el Desafío Diario con 100% de aciertos', 'Marcó en todas las fases eliminatorias del torneo (octavos, cuartos, semis y final), completando el palmarés más perfecto de un futbolista en la historia.', 250),
  ('lc-bolt-berlin-relic', 'deportes', 'reliquia', 'Usain Bolt y el Relámpago de 9,58 Segundos', 'Atletismo Mundial · Berlín, Alemania', '2009 d.C.', '''No te pongas límites, no hay nada imposible.'' — Usain Bolt', 'La redefinición de los límites de la biomecánica humana celebrada con carisma y alegría contagiosa.', 'Gana un Duelo en Deportes con más de 800 puntos', 'Alcanzó una velocidad punta de 44,72 km/h entre los metros 60 y 80, la mayor velocidad jamás desarrollada por un ser humano a pie.', 190)
